// Rankea las tendencias de SearXNG y arma la seccion 3 del Brief Diario.
// No copiar identidad de creadores: solo estructura/tema accionable.
const payload = items[0].json || {};
const results = Array.isArray(payload.results) ? payload.results : [];
const seen = new Set();
const top = [];
for (const r of results) {
  const title = (r.title || '').trim();
  if (!title) continue;
  const key = title.toLowerCase().slice(0, 60);
  if (seen.has(key)) continue;
  seen.add(key);
  top.push({ title, url: r.url || '', engine: r.engine || '' });
  if (top.length >= 3) break;
}
const date = new Date().toLocaleDateString('es-BO', { timeZone: 'America/La_Paz' });
const lines = [`ONIA | Recomendaciones y tendencias ${date}`, ''];
if (top.length === 0) {
  lines.push('Sin senal fuerte hoy en SearXNG. Revisar radar-creativo-onia manualmente.');
} else {
  top.forEach((t, i) => {
    lines.push(`${i + 1}. ${t.title}`);
    lines.push(`   Accion ONIA: convertir en carrusel/guion o angulo de venta. Fuente: ${t.url}`);
  });
}
lines.push('');
lines.push('Regla: inspiracion estructural, no copiar voz/identidad. Nada se publica sin aprobacion.');
const text = lines.join('\n').slice(0, 3900);
return [{ json: { date, count: top.length, text, trends: top } }];
